 jp_read:{task:'短い段落や物語の場面を一つ選び、本文の根拠から問いに答えよう。',steps:['問いの条件語に丸をつける','本文の候補に線を引き、問いと合う根拠を選ぶ','根拠と答えをつなげて短く説明する'],fields:[{label:'問い・場面',prompt:'何を答えるか、問いの言葉に印をつけよう。'},{label:'本文の根拠',prompt:'答えにつながる言葉・行・場面を示そう。'},{label:'答え・まとめ',prompt:'本文の根拠を一つ使って答えよう。'}],transfer:'別の問いでも、本文の根拠と答えを対応させる。'},
 jp_write:{task:'伝えたいことを一つ決め、考え・理由・例を順に並べて文章にしよう。',steps:['伝えたいことを一文か選択肢で決める','理由や出来事のカードを一つ選んで順に並べる','文型を使って一文を書き、伝わるか読み返す'],fields:[{label:'伝えたいこと',prompt:'まず自分の考えを一つ選ぶか、話してから書こう。'},{label:'理由・出来事・具体例',prompt:'考えを支える理由や例を一つ選ぼう。'},{label:'できた一文',prompt:'「私は〜。理由は〜。」などの型で書こう。'}],transfer:'自分で選んだ一か所だけ読み返し、次に直す所を決める。'},
 jp_notes:{task:'板書を全部写す代わりに、授業の大事な語と次の課題を短く残そう。',steps:['今日の題とキーワードを先に見る','説明を聞く時と書く時を分け、配布資料の空欄に要点を残す','書いた要点を見て、次にする課題を確かめる'],fields:[{label:'今日の題・キーワード',prompt:'板書や配布資料から大事な語を選ぼう。'},{label:'説明の要点',prompt:'短い言葉・図・穴埋めで残そう。'},{label:'次にする課題',prompt:'要点を手掛かりに、次の行動を一つ書こう。'}],transfer:'別の説明でも、聞く・書くを分けて要点を残す。'},
 en_sound:{task:'練習する英単語を一つ選び、音のまとまりと文字パターンを対応させよう。',steps:['先生の見本を聞き、口の形と目標の音を確かめる','音を小さなまとまりに分け、同じ音を表す文字に印をつける','文字カードで確かめ、似た新しい語でも試す'],fields:[{label:'練習する英単語・意味',prompt:'単語を一つ選び、知っている意味や絵を結びつけよう。'},{label:'音と文字の対応',prompt:'音のまとまりを分け、対応する文字パターンに印をつけよう。'},{label:'新しい語で試す',prompt:'見本と同じパターンを探し、読めたか確かめよう。'}],transfer:'未学習の語でも、同じ音と文字の対応を一つ使えるか試す。'},
 en_spell:{task:'英単語の意味から音を思い出し、音のまとまりごとに文字を並べよう。',steps:['意味・絵と対象語を確かめる','音のまとまりを区切り、文字カードや枠に対応させる','見本を隠して書き、違う所を自分で直す'],fields:[{label:'英単語・意味',prompt:'今日練習する語を少数選び、意味を確認しよう。'},{label:'音のまとまり／文字枠',prompt:'聞こえる順に音を分け、文字を一つずつ置こう。'},{label:'見本を隠した後',prompt:'思い出して書き、直した文字に印をつけよう。'}],transfer:'少し時間を空けてもう一度思い出し、明日も確認する語に印をつける。'},
 en_recall:{task:'単語を何度も見直すだけでなく、見本を隠して思い出す練習をしよう。',steps:['少数の単語を意味・音・例文と一緒に確かめる','カードを裏返し、意味や音から単語を思い出す','答え合わせをして、次に確かめる語を選ぶ'],fields:[{label:'今日の練習語',prompt:'一度に扱う語を少数選ぼう。'},{label:'見本を隠して想起',prompt:'意味・音・例文の手掛かりから思い出そう。'},{label:'次回・翌日の確認',prompt:'思い出せた語と、もう一度見る語を分けよう。'}],transfer:'翌日に同じ語をもう一度思い出し、手掛かりの有無を記録する。'},
 en_grammar:{task:'語句カードを並べ、英文の骨格と動詞の形を確かめよう。',steps:['主語・動詞など文の役割を色や枠で分ける','カードを並べて肯定文・否定文・疑問文の型を作る','一語を入れ替え、新しい文でも語順を確かめる'],fields:[{label:'使う語句・文型',prompt:'語句カードや見本の英文を選ぼう。'},{label:'英文の骨格',prompt:'主語・動詞・目的語などの順を枠で示そう。'},{label:'作った文・確かめ',prompt:'語を入れ替えた文を書き、型が合うか見よう。'}],transfer:'別の主語や語句でも文型を選び、理由を一つ説明する。'},
 en_chunk:{task:'英文を意味のまとまりで区切り、まとまりごとの意味をつないで読もう。',steps:['英文に意味の切れ目を入れる','短いまとまりごとに意味を確認し、順に並べる','一文全体の内容を一言で説明する'],fields:[{label:'今日読む英文',prompt:'教科書・プリントから短い一文を選ぼう。'},{label:'意味のまとまり',prompt:'スラッシュで区切り、まとまりごとの意味を書こう。'},{label:'文全体の意味',prompt:'まとまりをつないで、文の内容を説明しよう。'}],transfer:'別の短文でも、語ごとではなくまとまりごとに意味をつなぐ。'},
 en_listen:{task:'聞く前に目的を一つ決め、音声から必要な情報を拾おう。',steps:['場面や選択肢を見て、何を聞き取るか決める','短い音声を聞き、聞こえた語・情報に印をつける','必要ならもう一度聞き、選んだ答えを確かめる'],fields:[{label:'聞く目的',prompt:'人・場所・時・行動など、探す情報を一つ選ぼう。'},{label:'聞こえた手掛かり',prompt:'聞こえた語や音をメモ・選択肢で示そう。'},{label:'答え・確認',prompt:'手掛かりを使って答えを選び、確認しよう。'}],transfer:'別の短い音声でも、決めた情報を一つ拾えるか試す。'},
 en_output:{task:'伝えたい内容を選び、語句バンクと文型を使って英語で表そう。',steps:['伝えたいことを日本語・絵・選択肢で決める','使える語句と文型を選び、一文を組み立てる','書く・話す・録音など安心できる方法で伝える'],fields:[{label:'伝えたい内容',prompt:'相手に伝えたいことを一つ選ぼう。'},{label:'使う語句・文型',prompt:'語句バンクや見本から必要なものを選ぼう。'},{label:'できた英文・伝え方',prompt:'一文を作り、相手に伝わったか確かめよう。'}],transfer:'本人が選んだ方法で一度伝え、直したい所を一つ選ぶ。'},
